"""rival_bot: ICM-aware, range-modelling NLHE SNG bot. Pure standard library."""
import random
import time
from bisect import bisect_right
try:
    from kit import Agent
except Exception:  # pragma: no cover
    class Agent(object):
        def new_table(self, rules, seat, n_players): pass
        def act(self, obs): raise NotImplementedError
        def hand_end(self, result): pass

EQ_HEX = ''
RND_HEX = ''


# ---------------------------------------------------------------- evaluator
K5 = [5 ** r for r in range(13)]
KC = [5 ** (c >> 2) for c in range(52)]
RV = {}
FV = [0] * 8192
_STR = [(0x1F << (t - 4), t) for t in range(12, 3, -1)] + [((1 << 12) | 0xF, 3)]


def _vcounts(cnt):
    mask = 0
    for r in range(13):
        if cnt[r]:
            mask |= 1 << r
    qu = tr = None
    prs = []
    sg = []
    trs = []
    for r in range(12, -1, -1):
        c = cnt[r]
        if c >= 4 and qu is None: qu = r
        elif c == 3: trs.append(r)
        elif c == 2: prs.append(r)
        elif c == 1: sg.append(r)
    if qu is not None:
        k = 0
        for r in range(12, -1, -1):
            if cnt[r] and r != qu: k = r; break
        return (7 << 20) | (qu << 16) | (k << 12)
    if trs and (len(trs) >= 2 or prs):
        t = trs[0]
        p = max(([trs[1]] if len(trs) > 1 else []) + prs[:1])
        return (6 << 20) | (t << 16) | (p << 12)
    for m, top in _STR:
        if mask & m == m:
            return (4 << 20) | (top << 16)
    if trs:
        t = trs[0]
        ks = [r for r in range(12, -1, -1) if cnt[r] and r != t][:2]
        return (3 << 20) | (t << 16) | (ks[0] << 12) | (ks[1] << 8)
    if len(prs) >= 2:
        p1, p2 = prs[0], prs[1]
        k = max([r for r in range(13) if cnt[r] and r != p1 and r != p2])
        return (2 << 20) | (p1 << 16) | (p2 << 12) | (k << 8)
    if prs:
        p = prs[0]
        ks = [r for r in range(12, -1, -1) if cnt[r] and r != p][:3]
        return (1 << 20) | (p << 16) | (ks[0] << 12) | (ks[1] << 8) | (ks[2] << 4)
    ks = sg[:5]
    return (ks[0] << 16) | (ks[1] << 12) | (ks[2] << 8) | (ks[3] << 4) | ks[4]


def _build_eval():
    cnt = [0] * 13

    def rec(r, left, key, n):
        for c in range(0, (4 if left > 4 else left) + 1):
            cnt[r] = c
            k2 = key + c * K5[r]
            if c and n + c >= 5:
                RV[k2] = _vcounts(cnt)
            if left - c > 0 and r < 12:
                rec(r + 1, left - c, k2, n + c)
        cnt[r] = 0
    rec(0, 7, 0, 0)
    for m in range(8192):
        if bin(m).count('1') >= 5:
            v = 0
            for sm, top in _STR:
                if m & sm == sm:
                    v = (8 << 20) | (top << 16); break
            if not v:
                ks = [r for r in range(12, -1, -1) if m >> r & 1][:5]
                v = (5 << 20) | (ks[0] << 16) | (ks[1] << 12) | (ks[2] << 8) | (ks[3] << 4) | ks[4]
            FV[m] = v


_build_eval()


def evaluate(cards):
    key = 0
    m = [0, 0, 0, 0]
    for c in cards:
        key += KC[c]
        m[c & 3] |= 1 << (c >> 2)
    v = RV[key]
    f = FV[m[0]] or FV[m[1]] or FV[m[2]] or FV[m[3]]
    return f if f > v else v

# ---------------------------------------------------------------- preflop tables
EQ = [[int(EQ_HEX[3 * (i * 169 + j):3 * (i * 169 + j) + 3], 16) / 4095.0 for j in range(169)] for i in range(169)]
RND = [[0.0] + [int(RND_HEX[3 * (i * 7 + n):3 * (i * 7 + n) + 3], 16) / 4095.0 for n in range(7)] for i in range(169)]
COMB = [6 if i // 13 == i % 13 else (4 if i // 13 > i % 13 else 12) for i in range(169)]
ORDER = sorted(range(169), key=lambda i: -RND[i][1])        # heads-up strength order
CC = [0.0]
for _i in ORDER:
    CC.append(CC[-1] + COMB[_i])
PCT = [0.0] * 169                                             # fraction of combos stronger (0 = AA)
for _k, _i in enumerate(ORDER):
    PCT[_i] = (CC[_k] + COMB[_i] * 0.5) / 1326.0
ORDER_M = sorted(range(169), key=lambda i: -(RND[i][2] + RND[i][3]))   # multiway playability order
PCTM = [0.0] * 169
_c = 0.0
for _i in ORDER_M:
    PCTM[_i] = (_c + COMB[_i] * 0.5) / 1326.0
    _c += COMB[_i]
CE = []
for _i in range(169):
    row = [0.0]
    acc = 0.0
    Ei = EQ[_i]
    for _j in ORDER:
        acc += COMB[_j] * Ei[_j]
        row.append(acc)
    CE.append(row)


def eq_top(h, x):
    """Equity of class h vs top-x fraction of hands (heads-up order)."""
    if x >= 0.999:
        return RND[h][1]
    t = x * 1326.0
    if t < 6.0:
        t = 6.0
    k = bisect_right(CC, t) - 1
    if k >= 169:
        return RND[h][1]
    j = ORDER[k]
    return (CE[h][k] + (t - CC[k]) * EQ[h][j]) / t


# fraction of hands that would call a shove needing equity r, for several perceived shove widths
REFW = [0.04, 0.08, 0.12, 0.18, 0.25, 0.33, 0.42, 0.55, 0.7, 0.85, 1.0]
CALLT = []
for _w in REFW:
    _ref = sorted(eq_top(i, _w) for i in range(169) for _ in range(COMB[i]))
    CALLT.append([1.0 - bisect_right(_ref, _r / 100.0) / 1326.0 for _r in range(101)])


def callw(r, wref=0.4):
    if r <= 0: return 1.0
    if r >= 1: return 0.0
    k = bisect_right(REFW, wref) - 1
    if k < 0: k = 0; fr = 0.0
    elif k >= len(REFW) - 1: k = len(REFW) - 2; fr = 1.0
    else: fr = (wref - REFW[k]) / (REFW[k + 1] - REFW[k])
    x = r * 100.0
    i = int(x)
    if i >= 100: i = 99
    d = x - i
    a = CALLT[k]; b = CALLT[k + 1]
    va = a[i] + (a[i + 1] - a[i]) * d
    vb = b[i] + (b[i + 1] - b[i]) * d
    return va + (vb - va) * fr


RHO_W = 10.0
RHO_A = 0.55
RHO_B = 0.25
OPEN_PRIOR = [0.55, 0.45, 0.40, 0.30, 0.24, 0.19, 0.16, 0.14]
PUSHW10 = [0.9, 0.58, 0.38, 0.27, 0.21, 0.16, 0.13, 0.11, 0.10, 0.09]


def perceived_w(nb, depth):
    """Rough equilibrium-like shove width for a first-in shove with nb players behind at depth bb."""
    if nb < 0: nb = 0
    if nb > 9: nb = 9
    if depth < 1: depth = 1.0
    w = PUSHW10[nb] * (10.0 / depth) ** 0.75
    return 1.0 if w > 1 else (0.03 if w < 0.03 else w)


def hclass(h):
    a, b = h[0] >> 2, h[1] >> 2
    if a < b: a, b = b, a
    if a == b: return a * 13 + a
    if (h[0] & 3) == (h[1] & 3): return a * 13 + b
    return b * 13 + a


# ---------------------------------------------------------------- ICM (10/7/5/4/3/2/1/0)
PTS = [10, 7, 5, 4, 3, 2, 1, 0]


def icm(me, others):
    """Hero equity in points. others: list of positive stacks of other alive players."""
    no = len(others)
    if me <= 0:
        return PTS[no] if no < 8 else 0
    T = me
    for s in others: T += s
    e = 8 - (no + 1) + 3.0 * me / T
    for s in others:
        e += me / (me + s) + s / T * me / (T - s)
    return e


# ---------------------------------------------------------------- postflop strength
PC4 = [bin(_m).count('1') for _m in range(16)]
KP = [[K5[a] + K5[b] for b in range(13)] for a in range(13)]


def board_groups(hole, board, w):
    """Enumerate opponent holdings (grouped by ranks/suit class) weighted by class weights w.
    Returns my value and list of (value, weight)."""
    my = evaluate(list(hole) + list(board))
    am = [15] * 13
    for c in hole:
        am[c >> 2] &= ~(1 << (c & 3))
    base = 0
    sc = [0, 0, 0, 0]
    for c in board:
        am[c >> 2] &= ~(1 << (c & 3))
        base += KC[c]
        sc[c & 3] += 1
    fs = -1
    for s in range(4):
        if sc[s] >= 3: fs = s
    out = []
    app = out.append
    if fs < 0:
        for r1 in range(13):
            m1 = am[r1]
            if not m1: continue
            n1 = PC4[m1]
            row = KP[r1]
            if n1 >= 2:
                wt = w[r1 * 13 + r1]
                if wt > 0:
                    app((RV[base + row[r1]], wt * (n1 * (n1 - 1) >> 1)))
            r1o = r1 * 13
            for r2 in range(r1 + 1, 13):
                m2 = am[r2]
                if not m2: continue
                ws = w[r2 * 13 + r1]
                wo = w[r1o + r2]
                com = PC4[m1 & m2]
                wt = ws * com + wo * (n1 * PC4[m2] - com)
                if wt > 0:
                    app((RV[base + row[r2]], wt))
        return my, out
    bfm = 0
    for c in board:
        if c & 3 == fs: bfm |= 1 << (c >> 2)
    fb = 1 << fs
    for r1 in range(13):
        m1 = am[r1]
        if not m1: continue
        n1 = PC4[m1]
        row = KP[r1]
        f1 = 1 if m1 & fb else 0
        if n1 >= 2:
            wt = w[r1 * 13 + r1]
            if wt > 0:
                vnf = RV[base + row[r1]]
                tot = n1 * (n1 - 1) >> 1
                if f1:
                    vf = FV[bfm | (1 << r1)]
                    app((vf if vf > vnf else vnf, wt * (n1 - 1)))
                    if tot - (n1 - 1): app((vnf, wt * (tot - (n1 - 1))))
                else:
                    app((vnf, wt * tot))
        r1o = r1 * 13
        for r2 in range(r1 + 1, 13):
            m2 = am[r2]
            if not m2: continue
            ws = w[r2 * 13 + r1]
            wo = w[r1o + r2]
            if ws <= 0 and wo <= 0: continue
            n2 = PC4[m2]
            vnf = RV[base + row[r2]]
            com = PC4[m1 & m2]
            f2 = 1 if m2 & fb else 0
            if f1 and f2 and ws > 0:
                vf = FV[bfm | (1 << r1) | (1 << r2)]
                app((vf if vf > vnf else vnf, ws))
            if f1 and wo > 0 and n2 - f2:
                vf = FV[bfm | (1 << r1)]
                app((vf if vf > vnf else vnf, wo * (n2 - f2)))
            if f2 and wo > 0 and n1 - f1:
                vf = FV[bfm | (1 << r2)]
                app((vf if vf > vnf else vnf, wo * (n1 - f1)))
            sn = com - (1 if (f1 and f2) else 0)
            on = (n1 - f1) * (n2 - f2) - sn
            wt = ws * sn + wo * on
            if wt > 0: app((vnf, wt))
    return my, out


def eq_from_groups(my, groups, fp):
    """(eq vs whole weighted range, eq vs top-fp of range by current value)."""
    tot = 0.0
    win = 0.0
    for v, wt in groups:
        tot += wt
        if my > v: win += wt
        elif my == v: win += 0.5 * wt
    if tot <= 0:
        return 0.5, 0.5
    eall = win / tot
    if fp >= 0.999:
        return eall, eall
    target = fp * tot
    gs = sorted(groups, reverse=True)
    acc = 0.0
    w2 = 0.0
    for v, wt in gs:
        take = wt if acc + wt <= target else target - acc
        if take <= 0: break
        acc += take
        if my > v: w2 += take
        elif my == v: w2 += 0.5 * take
    etop = w2 / acc if acc > 0 else eall
    return eall, etop


def top_eq(my, gs, tot, fp):
    """Equity vs the top-fp share (by value) of pre-sorted groups gs with total weight tot."""
    if tot <= 0:
        return 0.5
    target = fp * tot
    acc = 0.0
    w2 = 0.0
    for v, wt in gs:
        take = wt if acc + wt <= target else target - acc
        if take <= 0: break
        acc += take
        if my > v: w2 += take
        elif my == v: w2 += 0.5 * take
    return w2 / acc if acc > 0 else 0.5


def draw_outs(hole, board):
    """Rough count of clean-ish outs to a strong hand and whether we have a made flush/straight."""
    cards = list(hole) + list(board)
    sc = [0, 0, 0, 0]
    for c in cards: sc[c & 3] += 1
    bsc = [0, 0, 0, 0]
    for c in board: bsc[c & 3] += 1
    outs = 0.0
    made = False
    for s in range(4):
        if sc[s] >= 5: made = True
        elif sc[s] == 4 and sc[s] - bsc[s] >= 1:
            outs += 9 if sc[s] - bsc[s] == 2 else 7  # one-card flush draw weaker
        elif sc[s] == 3 and len(board) == 3 and sc[s] - bsc[s] == 2:
            outs += 1.2  # backdoor
    m = 0
    for c in cards: m |= 1 << (c >> 2)
    if m >> 12 & 1: m2 = (m << 1) | 1
    else: m2 = m << 1
    bm = 0
    for c in board: bm |= 1 << (c >> 2)
    if bm >> 12 & 1: bm2 = (bm << 1) | 1
    else: bm2 = bm << 1
    have = False
    for t in range(4, 14):
        sm = 0x1F << (t - 4)
        if m2 & sm == sm: have = True
    if have:
        made = True
    else:
        ranks = 0
        for x in range(13):
            if m >> x & 1: continue
            mx = m2 | (1 << (x + 1)) | (2 if x == 12 else 0)
            bx = bm2 | (1 << (x + 1)) | (2 if x == 12 else 0)
            for t in range(4, 14):
                sm = 0x1F << (t - 4)
                if mx & sm == sm and bx & sm != sm:
                    ranks += 1
                    break
        outs += 3.6 * ranks if ranks <= 2 else 8
    return outs, made


# ---------------------------------------------------------------- opponent model
class Opp(object):
    __slots__ = ('n_pf', 'vpip', 'pfr', 'n_un', 'opn', 'n_fr', 'fr_f', 'fr_c', 'fr_r', 'big', 'n_fa', 'fa_c',
                 'n_nb', 'nb_b', 'n_fb', 'fb_f', 'fb_c', 'fb_r', 'sd_n', 'sd_sum')

    def __init__(self):
        for k in self.__slots__:
            setattr(self, k, 0)

    def vp(self):
        return (self.vpip + 2.5) / (self.n_pf + 10.0)

    def pr(self):
        return (self.pfr + 1.5) / (self.n_pf + 10.0)

    def openr(self):
        return (self.opn + 1.8) / (self.n_un + 8.0)

    def rho(self):
        # how random / maniacal the player looks (0..1); weak prior so random bots are spotted early
        v = (self.vpip + 0.25 * RHO_W) / (self.n_pf + RHO_W)
        x = (v - RHO_A) / RHO_B
        return 0.0 if x < 0 else (1.0 if x > 1 else x)

    def agg(self):
        return (self.nb_b + 1.4) / (self.n_nb + 4.0)

    def rho_post(self):
        # randomness of postflop aggression: loose AND frequently aggressive (stations are loose but passive)
        a = (self.nb_b + self.fb_r + 1.0) / (self.n_nb + self.n_fb + 4.0)
        x = (a - 0.12) / 0.2
        x = 0.0 if x < 0 else (1.0 if x > 1 else x)
        return self.rho() * x

    def callrate(self):
        # how often they continue facing a preflop raise
        return (self.fr_c + self.fr_r + 1.2) / (self.n_fr + 4.0)

    def foldbet(self):
        return (self.fb_f + 1.6) / (self.n_fb + 4.0)

    def raisebet(self):
        return (self.fb_r + 0.4) / (self.n_fb + 4.0)

    def foldraise(self):
        return (self.fr_f + 2.4) / (self.n_fr + 4.0)

    def bigrate(self):
        return (self.big + 0.2) / (self.n_pf + 6.0)


class Replay(object):
    """Re-runs the betting of the current hand from obs.history to give context for each action."""

    def __init__(self, obs, bot):
        n = len(obs.stacks)
        self.n = n
        self.me = bot.seat
        self.opp = bot.opp
        sb_amt, bb_amt = obs.blinds
        self.bb = bb_amt
        self.sbamt = sb_amt
        chips = [obs.stacks[i] + obs.bets[i] for i in range(n)]
        self.alive = [chips[i] > 0 for i in range(n)]
        al = [i for i in range(n) if self.alive[i]]
        btn = obs.button

        def nxt(s):
            for k in range(1, n + 1):
                j = (s + k) % n
                if self.alive[j]: return j
            return s
        if len(al) == 2:
            sb = btn if self.alive[btn] else nxt(btn); bb = nxt(sb)
        else:
            sb = nxt(btn); bb = nxt(sb)
        self.sb, self.bbs = sb, bb
        self.rem = list(chips)
        self.rb = [0] * n
        for s, a in ((sb, sb_amt), (bb, bb_amt)):
            x = min(a, self.rem[s]); self.rem[s] -= x; self.rb[s] += x
        self.cur = max(self.rb)
        self.last = bb_amt
        self.street = 0
        self.acted = set()
        self.folded = [not self.alive[i] for i in range(n)]
        self.idx = 0
        self.nraise = 0
        self.pf_done = [False] * n
        self.pfa = [None] * n          # preflop action class this hand
        self.pfnr = [0] * n           # number of raises before this player's last preflop raise
        self.pfcall = [False] * n     # raised, then called a re-raise
        self.post_aggr = [0] * n
        self.post_calls = [0] * n
        self.last_aggr = None          # last aggressor seat (any street)
        self.pf_aggr = None            # preflop last raiser
        self.street_aggr = None
        self.skip_blinds = True
        self.ok = True

    def behind_count(self, s):
        # alive seats acting after s up to and including the big blind (preflop)
        if s == self.bbs:
            return 0
        c = 0
        for k in range(1, self.n):
            j = (s + k) % self.n
            if self.alive[j]:
                c += 1
            if j == self.bbs:
                break
        return c

    def feed(self, hist):
        if not self.ok or hist is None:
            return
        try:
            if self.skip_blinds and len(hist) >= 2:
                self.skip_blinds = False
                (s0, a0), (s1, a1) = hist[0], hist[1]
                k0, k1 = a0[0], a1[0]
                v0 = a0[1] if len(a0) > 1 else 0
                v1 = a1[1] if len(a1) > 1 else 0
                if k0 not in ('fold', 'check') and k1 not in ('fold', 'check') and s0 != s1 and \
                        0 < v0 <= self.sbamt and 0 < v1 <= self.bb and v1 >= v0 and \
                        (s0 == self.sb or s1 == self.bbs or v1 == self.bb):
                    if s0 != self.sb or s1 != self.bbs:
                        # trust the posts for blind positions
                        self.sb, self.bbs = s0, s1
                    self.idx = 2
            elif self.skip_blinds and len(hist) == 1:
                (s0, a0) = hist[0]
                v0 = a0[1] if len(a0) > 1 else 0
                if s0 == self.sb and a0[0] not in ('fold', 'check', 'call') and 0 < v0 <= self.sbamt:
                    pass  # wait for more entries before deciding
                else:
                    self.skip_blinds = False
            while self.idx < len(hist):
                e = hist[self.idx]
                self.idx += 1
                self._one(e)
        except Exception:
            self.ok = False

    def _one(self, e):
        s, act = e
        kind = act[0]
        amt = act[1] if len(act) > 1 else 0
        n = self.n
        if kind not in ('fold', 'check', 'call', 'raise'):
            return
        if s < 0 or s >= n:
            return
        me = self.me
        st = self.street
        facing = self.cur - self.rb[s]
        o = self.opp[s] if s != me else None
        if o is not None and facing > 0 and facing >= 0.5 * self.rem[s] and kind in ('fold', 'call', 'raise'):
            o.n_fa += 1
            if kind != 'fold':
                o.fa_c += 1
        if st == 0:
            if o is not None:
                if not self.pf_done[s]:
                    bbcheck = (s == self.bbs and facing <= 0 and kind == 'check')
                    if not bbcheck:
                        self.pf_done[s] = True
                        o.n_pf += 1
                        if kind in ('call', 'raise'): o.vpip += 1
                        if kind == 'raise': o.pfr += 1
                        if self.nraise == 0:
                            o.n_un += 1
                            if kind == 'raise': o.opn += 1
                if self.nraise >= 1 and facing > 0:
                    o.n_fr += 1
                    if kind == 'fold': o.fr_f += 1
                    elif kind == 'call': o.fr_c += 1
                    elif kind == 'raise': o.fr_r += 1
                if kind == 'raise':
                    put = amt - self.rb[s]
                    if put >= 0.45 * (self.rem[s] + 0.0) or put >= self.rem[s]:
                        o.big += 1
            if kind == 'raise':
                self.pfnr[s] = self.nraise
                if self.nraise == 0: self.pfa[s] = 'open'
                elif self.nraise == 1: self.pfa[s] = '3bet'
                else: self.pfa[s] = '4bet'
                put = amt - self.rb[s]
                if put >= self.rem[s] * 0.9: self.pfa[s] = 'allin' if self.nraise >= 0 else self.pfa[s]
            elif kind == 'call':
                if self.pfa[s] is None or self.pfa[s] in ('limp', 'call'):
                    self.pfa[s] = 'limp' if self.nraise == 0 else 'call'
                elif self.pfa[s] in ('open', '3bet') and facing > 0:
                    self.pfcall[s] = True
            elif kind == 'check':
                if self.pfa[s] is None: self.pfa[s] = 'check'
        else:
            if o is not None:
                if facing > 0:
                    o.n_fb += 1
                    if kind == 'fold': o.fb_f += 1
                    elif kind == 'call': o.fb_c += 1
                    elif kind == 'raise': o.fb_r += 1
                else:
                    o.n_nb += 1
                    if kind == 'raise': o.nb_b += 1
            if kind == 'raise':
                self.post_aggr[s] += 1
            elif kind == 'call':
                self.post_calls[s] += 1
        # apply
        if kind == 'fold':
            self.folded[s] = True
        elif kind == 'call':
            x = min(max(0, self.cur - self.rb[s]), self.rem[s])
            self.rem[s] -= x; self.rb[s] += x
        elif kind == 'raise':
            x = min(max(0, amt - self.rb[s]), self.rem[s])
            self.rem[s] -= x; self.rb[s] += x
            inc = self.rb[s] - self.cur
            if inc > 0:
                if inc >= self.last: self.last = inc
                self.cur = self.rb[s]
                self.acted = set()
                self.nraise += 1
                self.last_aggr = s
                self.street_aggr = s
                if st == 0: self.pf_aggr = s
        self.acted.add(s)
        # round end?
        act_pl = [i for i in range(n) if not self.folded[i]]
        if len(act_pl) <= 1:
            return
        can = [i for i in act_pl if self.rem[i] > 0]
        done = True
        for i in can:
            if i not in self.acted or self.rb[i] < self.cur:
                done = False; break
        if done:
            self.street += 1
            self.rb = [0] * n
            self.cur = 0
            self.last = self.bb
            self.acted = set()
            self.street_aggr = None


# ---------------------------------------------------------------- the bot
class Bot(Agent):
    # tunables
    DEBUG = False
    AGG = 1.0          # preflop open width multiplier
    PUSH_BB = 14.0     # push/fold below this many bb effective
    CALL_MARGIN = 0.0  # icm call margin (points)
    PUSH_MARGIN = 0.0
    BL0 = 0.12
    PREM0 = 0.02       # assumed ICM premium of callers facing our shove
    PREM1 = 0.04
    FOLD_TAX = 0.5     # fraction of an orbit's blinds charged to a preflop fold (blind pressure)

    def __init__(self):
        self.rng = random.Random()
        self.seat = 0
        self.n = 8
        self.opp = [Opp() for _ in range(10)]
        self.rp = None
        self.hand = -1
        self.cap = 200
        self._fc = 1.0

    def new_table(self, rules, seat, n_players):
        try:
            self.seat = seat
            self.n = n_players or 8
        except Exception:
            self.n = 8
        self.opp = [Opp() for _ in range(max(10, (n_players or 8) + 2))]
        self.rp = None
        self.hand = -1
        self.cap = 200
        try:
            if isinstance(rules, dict):
                for k in ('hand_cap', 'max_hands', 'hands', 'cap', 'hand_limit'):
                    v = rules.get(k)
                    if isinstance(v, int) and v > 10:
                        self.cap = v
                        break
        except Exception:
            pass
        try:
            self.rng.seed(random.getrandbits(32) ^ (int(time.time() * 1e6) & 0xFFFFFFFF))
        except Exception:
            pass

    def hand_end(self, result):
        try:
            if self.rp is not None and isinstance(result, dict):
                h = result.get('history') or result.get('actions')
                if isinstance(h, (list, tuple)) and len(h) >= self.rp.idx:
                    self.rp.feed(h)
                sd = result.get('showdown') or result.get('shown') or result.get('hands')
                if isinstance(sd, dict):
                    for s, hc in sd.items():
                        try:
                            s = int(s)
                            if s != self.seat and 0 <= s < len(self.opp) and len(hc) == 2:
                                o = self.opp[s]
                                o.sd_n += 1
                                o.sd_sum += RND[hclass(hc)][1]
                        except Exception:
                            pass
        except Exception:
            pass
        self.rp = None

    # -------------------------------------------------------------- helpers
    def _safe(self, obs):
        L = obs.legal
        if 'check' in L: return ('check', 0)
        if 'call' in L and obs.to_call <= 0: return ('call', 0)
        return ('fold', 0) if 'fold' in L else (('call', 0) if 'call' in L else ('check', 0))

    def _fix(self, obs, a):
        L = obs.legal
        k, amt = a
        if k == 'raise':
            if 'raise' not in L:
                return ('call', 0) if 'call' in L else ('check', 0)
            amt = int(amt)
            if amt < obs.min_raise: amt = obs.min_raise
            if amt > obs.max_raise: amt = obs.max_raise
            # raises close to all-in -> all-in
            if obs.max_raise - amt < 0.12 * (obs.max_raise - obs.bets[obs.seat]) or obs.max_raise - amt < obs.blinds[1]:
                amt = obs.max_raise
            return ('raise', int(amt))
        if k == 'fold' and 'check' in L:
            return ('check', 0)
        if k == 'check' and 'check' not in L:
            return ('fold', 0) if 'fold' in L else ('call', 0)
        if k == 'call' and 'call' not in L:
            return ('check', 0) if 'check' in L else ('fold', 0)
        if k not in L:
            return self._safe(obs)
        return (k, 0)

    def act(self, obs):
        try:
            self.t0 = time.perf_counter()
            if obs.hand_no != self.hand or self.rp is None:
                self.hand = obs.hand_no
                self.rp = Replay(obs, self) if obs.street == 0 else None
            if self.rp is not None:
                self.rp.feed(obs.history)
            if obs.street == 0:
                a = self.preflop(obs)
            else:
                a = self.postflop(obs)
            return self._fix(obs, a)
        except Exception:
            if self.DEBUG:
                raise
            try:
                return self._safe(obs)
            except Exception:
                return ('fold', 0)

    def totals(self, obs):
        return [obs.stacks[i] + obs.bets[i] for i in range(len(obs.stacks))]

    def opp_range_w(self, j, obs):
        """Class weights and width for opponent j's range given this hand's preflop actions."""
        o = self.opp[j]
        rp = self.rp
        pfa = rp.pfa[j] if rp is not None and rp.ok else None
        rho = o.rho()
        bb = obs.blinds[1]
        tot = obs.stacks[j] + obs.bets[j] + (obs.pot if obs.street == 0 else 0)
        if pfa == 'open':
            nb = rp.behind_count(j)
            prior = OPEN_PRIOR[nb if nb < 8 else 7]
            ob = (o.opn + 1.8) / (o.n_un + 8.0)
            f = prior * (ob / 0.225) ** 0.8
            if f > 1: f = 1.0
        elif pfa == '3bet':
            f = max(0.03, ((o.fr_r + 0.3) / (o.n_fr + 6.0)) * 0.9)
        elif pfa == '4bet':
            f = 0.035
        elif pfa == 'allin':
            depth = max(1.0, (rp.rem[j] + rp.rb[j]) / bb)
            nb = rp.behind_count(j)
            if rp.pfnr[j] == 0:
                f = perceived_w(nb, depth) * 0.85
            else:
                f = perceived_w(nb + 1, depth) * 0.55 * (1.0 + 0.5 * rp.pfnr[j] * 0) 
                if rp.pfnr[j] >= 2: f *= 0.6
            f = max(f, o.bigrate())
        elif pfa == 'call':
            f = min(0.6, o.vp() * 0.85)
        elif pfa == 'limp':
            f = min(0.85, o.vp() * 1.05)
        else:
            f = 1.0
        if rp is not None and rp.pfcall[j]:
            f *= 0.5
        if f > 1: f = 1.0
        if f < 0.025: f = 0.025
        self._raw = (f, rho)
        f = (1 - rho) * f + rho * 1.0
        if f > 1: f = 1.0
        return f

    def eq_vs(self, h, j, obs):
        """Preflop equity of class h vs opponent j's range as a proper mixture (tight range / random)."""
        self.opp_range_w(j, obs)
        f, rho = self._raw
        if rho <= 0:
            return eq_top(h, f)
        a = (1 - rho) * f
        return (a * eq_top(h, f) + rho * RND[h][1]) / (a + rho)

    def wvec(self, f, cap=None):
        if f >= 0.999:
            return ONES
        w = [0.0] * 169
        edge = 0.04
        lo = f - edge
        for i in range(169):
            p = PCT[i]
            if p <= lo: w[i] = 1.0
            elif p < f + edge: w[i] = (f + edge - p) / (2 * edge)
        return w

    # -------------------------------------------------------------- preflop
    def preflop(self, obs):
        me = obs.seat
        bb = obs.blinds[1]
        n = len(obs.stacks)
        tot = self.totals(obs)
        my_tot = tot[me]
        h = hclass(obs.hole)
        pct = PCT[h]
        opps = [j for j in range(n) if j != me and obs.in_hand[j]]
        cur = max(obs.bets)
        rp = self.rp
        nraise = rp.nraise if (rp is not None and rp.ok) else (0 if cur <= bb else 1)
        if not opps:
            return ('check', 0) if 'check' in obs.legal else ('call', 0)
        eff = min(my_tot, max(tot[j] for j in opps)) / float(bb)
        to_call = obs.to_call
        L = obs.legal
        # all-in or commit decisions
        if cur > bb and (to_call >= 0.35 * my_tot or eff <= self.PUSH_BB * 1.6 or cur >= 0.5 * my_tot):
            return self.pf_commit(obs, h, tot, opps)
        if cur <= bb:
            if eff <= self.PUSH_BB:
                return self.pf_push(obs, h, tot, opps)
            return self.pf_open(obs, h, tot, opps, eff)
        return self.pf_vs_raise(obs, h, tot, opps, eff)

    def behind(self, obs, opps):
        """opponents still to act behind us this round in order (for unopened pots)."""
        me = obs.seat
        n = len(obs.stacks)
        rp = self.rp
        res = []
        for k in range(1, n):
            j = (me + k) % n
            if j in opps:
                res.append(j)
        # trim: players after BB in order have acted already (they are before us); approximate by those who haven't acted
        if rp is not None and rp.ok:
            res = [j for j in res if not rp.pf_done[j] or rp.pfa[j] in (None, 'limp', 'check')]
            # place in action order: from us to BB
            bbs = rp.bbs
            order = []
            for k in range(1, n):
                j = (me + k) % n
                if j in res: order.append(j)
                if j == bbs: break
            if order or me == bbs:
                res = order + [j for j in res if j not in order]
        return res

    def call_prob(self, j, obs, tot, my_tot, dead, wref=0.4):
        """Probability opponent j calls our all-in, and the width of their calling range."""
        o = self.opp[j]
        bb = obs.blinds[1]
        risk = min(my_tot, tot[j])
        need = risk - obs.bets[j]
        if need <= 0:
            return 1.0, 1.0
        potw = risk + min(obs.bets[j], risk) + dead
        r = need / float(need + potw)
        nal = 0
        for x in tot:
            if x > 0: nal += 1
        icmf = 0.0 if nal <= 2 else (0.5 if nal == 3 else 1.0)
        prem = icmf * (self.PREM0 + self.PREM1 * min(1.0, need / float(max(1, tot[j]))))
        c = callw(r + prem, wref)
        pfa = self.rp.pfa[j] if (self.rp is not None and self.rp.ok) else None
        rho = o.rho()
        v = o.vp()
        loosef = 1.0 + 1.2 * (v - 0.25)
        if loosef < 0.6: loosef = 0.6
        c = c * loosef
        if pfa in ('open', '3bet', '4bet', 'call', 'limp'):
            f = self.opp_range_w(j, obs)
            if c > f: c = f
            p = c / f
            width = c
        else:
            p = c
            width = c
        if p > 1: p = 1.0
        if width > 1: width = 1.0
        if o.n_fa:
            # blend with how often this player has actually called big all-in bets
            p = (p * 3.0 + o.fa_c) / (3.0 + o.n_fa)
            if pfa not in ('open', '3bet', '4bet', 'call', 'limp'):
                width = p
        # randomness mixture: loose players continue at their observed rate
        prand = o.callrate()
        if prand < 0.5: prand = 0.5
        p_mix = (1 - rho) * p + rho * prand
        width_eq = width
        return p_mix, (rho * prand, (1 - rho) * p, width_eq)

    def shove_ev(self, obs, h, tot, opps, my_amt):
        """ICM EV of going all-in now (preflop)."""
        me = obs.seat
        n = len(obs.stacks)
        bets = obs.bets
        my_tot = tot[me]
        alive_others = [j for j in range(n) if j != me and tot[j] > 0]
        behind = [j for j in opps]
        pot_bets = sum(bets)
        # fold-around
        p_none = 1.0
        ev = 0.0
        st_other = {j: tot[j] - bets[j] for j in alive_others}
        # everyone folds: we win all bets
        win_all = my_tot + pot_bets - bets[me]
        # sequential first-caller model
        order = self.behind(obs, opps)
        for j in opps:
            if j not in order: order.append(j)
        evs_call = 0.0
        bb = obs.blinds[1]
        depth = my_tot / float(bb)
        if max(bets) > bb:
            wref = perceived_w(len(order) + 1, depth) * 0.7
        else:
            wref = perceived_w(len(order), depth)
        for j in order:
            dead = pot_bets - bets[me] - bets[j]
            p, info = self.call_prob(j, obs, tot, my_tot, dead, wref)
            if isinstance(info, tuple):
                pr_rand, pr_rat, width = info
                if pr_rand + pr_rat > 0:
                    e = (pr_rand * RND[h][1] + pr_rat * eq_top(h, width)) / (pr_rand + pr_rat)
                else:
                    e = eq_top(h, width)
            else:
                e = eq_top(h, 1.0)
            pc = p_none * p
            if pc > 1e-6:
                risk = min(my_tot, tot[j])
                oth_w = []
                oth_l = []
                for k in alive_others:
                    if k == j: continue
                    oth_w.append(st_other[k])
                    oth_l.append(st_other[k])
                mw = my_tot + risk + dead
                jl = tot[j] - risk
                ow = [x for x in oth_w if x > 0]
                if jl > 0: ow.append(jl)
                u_win = icm(mw, ow)
                ml = my_tot - risk
                jw = tot[j] + risk + dead
                ol = [x for x in oth_l if x > 0] + [jw]
                u_lose = icm(ml, ol)
                evs_call += pc * (e * u_win + (1 - e) * u_lose)
            p_none *= (1 - p)
        others_after = [st_other[k] for k in alive_others if st_other[k] > 0]
        u_steal = icm(win_all, others_after)
        return evs_call + p_none * u_steal, p_none

    def fold_ev(self, obs, tot):
        me = obs.seat
        n = len(obs.stacks)
        bets = obs.bets
        mx = max(range(n), key=lambda j: (bets[j], -((j - me) % n)) if j != me else (-1, 0))
        others = []
        pot = sum(bets) + obs.pot
        for j in range(n):
            if j == me or tot[j] <= 0 and j != mx: continue
            s = tot[j] - bets[j]
            if j == mx: s += pot
            if s > 0: others.append(s)
        mine = obs.stacks[me]
        if obs.street == 0 and self.FOLD_TAX > 0:
            sb, bb = obs.blinds
            left = self.cap - (obs.hand_no or 0)
            sc = 1.0 if left >= 15 else max(0.0, left / 15.0)
            mine = max(1, mine - self.FOLD_TAX * sc * (sb + bb) * 0.5)
        return icm(mine, others)

    def pf_push(self, obs, h, tot, opps):
        me = obs.seat
        bb = obs.blinds[1]
        L = obs.legal
        if 'raise' not in L:
            return ('call', 0) if 'call' in L else ('check', 0)
        ev_s, pn = self.shove_ev(obs, h, tot, opps, tot[me])
        if 'check' in L:
            # BB option: check is free; compare with check equity ~ fold-ish value + small realisation
            ev_f = self.fold_ev_check(obs, tot, h)
        else:
            ev_f = self.fold_ev(obs, tot)
        margin = self.PUSH_MARGIN + 0.004 * self.rng.random()
        if ev_s > ev_f + margin:
            return ('raise', obs.max_raise)
        # limp with strong-ish hand in SB vs BB? just fold/check
        if 'check' in L:
            return ('check', 0)
        return ('fold', 0)

    def fold_ev_check(self, obs, tot, h):
        # value of checking in BB: current stacks plus share of pot by equity (rough)
        me = obs.seat
        n = len(obs.stacks)
        others = [tot[j] for j in range(n) if j != me and tot[j] > 0]
        base = icm(tot[me], others)
        nop = len([j for j in range(n) if j != me and obs.in_hand[j]])
        e = RND[h][min(7, max(1, nop))]
        pot = sum(obs.bets)
        # approximate chip gain from playing the pot with equity e (realised ~80%)
        gain = (e * 0.85 * pot) - obs.bets[me] * 0 - (pot - obs.bets[me]) * 0
        exp = gain - obs.bets[me] * (1 - 0)  # chips we already put in are in pot
        dchips = e * 0.85 * pot - obs.bets[me]
        d = icm(max(1, tot[me] + dchips), others) - base
        return base + d

    def pf_open(self, obs, h, tot, opps, eff):
        me = obs.seat
        bb = obs.blinds[1]
        L = obs.legal
        rp = self.rp
        n = len(obs.stacks)
        beh = self.behind(obs, opps)
        nb = len(beh)
        limpers = [j for j in opps if obs.bets[j] >= bb and rp is not None and rp.ok and rp.pfa[j] == 'limp']
        # open width by number of players behind
        base = {0: 1.0, 1: 0.48, 2: 0.42, 3: 0.30, 4: 0.24, 5: 0.20, 6: 0.17, 7: 0.15}.get(nb, 0.14)
        # adapt to folding tendencies of players behind
        if beh:
            fr = sum(self.opp[j].foldraise() for j in beh) / len(beh)
            base *= 0.75 + 0.6 * fr
            # very loose callers behind: tighten a bit, value
            rh = max(self.opp[j].rho() for j in beh)
            base *= 1.0 - 0.25 * rh
        base *= self.AGG
        if limpers:
            base *= 0.75
        pct = PCT[h]
        pm = PCTM[h]
        score = min(pct, pm * 1.1 + 0.02)
        is_bb = (rp is not None and rp.ok and me == rp.bbs)
        if 'raise' in L and score < base:
            size = (2.2 + 0.3 * self.rng.random()) * bb + len(limpers) * bb
            if nb <= 1 and me != (rp.bbs if rp else -1):
                size = (2.2 + 0.4 * self.rng.random()) * bb
            if eff < 22:
                size = min(size, 2.2 * bb)
            return ('raise', int(max(obs.min_raise, max(obs.bets) + size - bb)))
        to_call = obs.to_call
        if 'check' in L:
            return ('check', 0)
        # cheap limp/overlimp/complete with playable hands when deep
        if to_call <= bb and eff > 30 and limpers and pm < 0.40:
            return ('call', 0)
        if to_call <= bb * 0.5 + 1 and eff > 25 and pm < 0.45 and is_bb is False and nb == 1:
            # SB complete vs BB occasionally
            if self.rng.random() < 0.35:
                return ('call', 0)
        return ('fold', 0)

    def pf_vs_raise(self, obs, h, tot, opps, eff):
        me = obs.seat
        bb = obs.blinds[1]
        L = obs.legal
        rp = self.rp
        cur = max(obs.bets)
        raisers = [j for j in opps if obs.bets[j] == cur]
        r = raisers[0] if raisers else opps[0]
        f = self.opp_range_w(r, obs)
        e = self.eq_vs(h, r, obs)
        n_in = len(opps)
        to_call = obs.to_call
        pot = sum(obs.bets) + obs.pot
        nraise = rp.nraise if (rp is not None and rp.ok) else 1
        callers = [j for j in opps if j != r and obs.bets[j] > bb * 0.99 and obs.bets[j] == cur]
        pm = PCTM[h]
        # 3bet / 4bet for value
        thr_v = 0.60 + 0.03 * (nraise - 1) + 0.02 * len(callers)
        if 'raise' in L and e >= thr_v:
            if nraise >= 2 or eff < 30:
                return ('raise', obs.max_raise)
            size = cur * 3 + sum(obs.bets[j] for j in callers)
            if size >= 0.4 * tot[me]:
                return ('raise', obs.max_raise)
            return ('raise', int(size))
        # bluff 3-bet with blockers vs wide/foldy raisers
        o = self.opp[r]
        if 'raise' in L and nraise == 1 and not callers and f > 0.22 and o.foldraise() > 0.45 and \
                0.12 < PCT[h] < 0.35 and (obs.hole[0] >> 2 == 12 or obs.hole[1] >> 2 == 12 or (obs.hole[0] & 3) == (obs.hole[1] & 3)) \
                and self.rng.random() < 0.35 and eff > 25:
            return ('raise', int(cur * 3))
        # call
        po = to_call / float(pot + to_call)
        implied = 0.0
        a, b = obs.hole[0] >> 2, obs.hole[1] >> 2
        if a == b and eff > 25:
            implied = 0.07 + min(0.05, (eff - 25) / 600.0)
        elif (obs.hole[0] & 3) == (obs.hole[1] & 3) and abs(a - b) <= 2 and eff > 35:
            implied = 0.04
        need = po + 0.06 + 0.02 * (nraise - 1) - implied + 0.03 * (to_call / float(max(1, tot[me])))
        if me != obs.button and eff > 25:
            need += 0.03
        # in BB we get a discount, multiway pot discount handled by po
        if e - need > 0 and to_call < 0.35 * tot[me]:
            if e > need + 0.0 or self.rng.random() < 0.5:
                return ('call', 0)
        return ('fold', 0) if 'fold' in L else ('check', 0)

    def pf_commit(self, obs, h, tot, opps):
        """Facing a raise with stacks shallow / big bets: shove, call all-in or fold by ICM."""
        me = obs.seat
        bb = obs.blinds[1]
        L = obs.legal
        rp = self.rp
        cur = max(obs.bets)
        my_tot = tot[me]
        n = len(obs.stacks)
        # aggressors' ranges
        aggs = [j for j in opps if obs.bets[j] > bb]
        if not aggs:
            aggs = [j for j in opps if obs.bets[j] == cur] or opps[:1]
        # equity vs all aggressors (multiway approx)
        inv = 0.0
        for j in aggs:
            o = self.opp[j]
            ej = self.eq_vs(h, j, obs)
            ej = min(0.99, max(0.01, ej))
            inv += (1 - ej) / ej
        e = 1.0 / (1.0 + inv)
        # can we be all-in by calling?
        to_call = obs.to_call
        others_alive = [j for j in range(n) if j != me and tot[j] > 0]
        # scenario: we call (or shove); assume aggressors' max commitment
        max_agg = max(tot[j] for j in aggs)
        allin_amt = my_tot
        if 'raise' in L and (cur < my_tot) and (max_agg > cur):
            # opponent has chips left: compare shove vs call-all vs fold
            pass
        risk = min(my_tot, max_agg)
        # chips in pot from non-aggressors / dead money
        dead = sum(obs.bets[j] for j in range(n) if j not in aggs and j != me) + obs.pot
        ag_put = sum(min(obs.bets[j], risk) if len(aggs) > 1 else min(tot[j], risk) for j in aggs)
        if len(aggs) > 1:
            ag_put = sum(min(tot[j], risk) for j in aggs)
        # win: we gain ag_put + dead
        oth = []
        for j in others_alive:
            if j in aggs:
                continue
            s = tot[j] - obs.bets[j]
            if s > 0: oth.append(s)
        win_oth = list(oth) + [tot[j] - min(tot[j], risk) for j in aggs if tot[j] - min(tot[j], risk) > 0]
        u_win = icm(my_tot + ag_put + dead, win_oth)
        # lose: biggest aggressor gets our chips
        lose_oth = list(oth)
        big = max(aggs, key=lambda j: tot[j])
        for j in aggs:
            s = tot[j] - min(tot[j], risk)
            if j == big:
                s = tot[j] + risk + dead + sum(min(tot[k], risk) for k in aggs if k != big)
            if s > 0: lose_oth.append(s)
        u_lose = icm(my_tot - risk, lose_oth)
        u_fold = self.fold_ev(obs, tot)
        need = (u_fold - u_lose) / (u_win - u_lose) if u_win > u_lose else 1.0
        # if we can shove and opponent hasn't committed, fold equity helps
        pfold = 0.0
        if 'raise' in L and max_agg > cur and len(aggs) == 1:
            j = aggs[0]
            o = self.opp[j]
            f = self.opp_range_w(j, obs)
            # they call our shove with top part of their range
            need_j = min(my_tot, tot[j]) - obs.bets[j]
            potw = min(my_tot, tot[j]) + obs.bets[j] + dead
            rj = need_j / float(need_j + potw) if need_j > 0 else 0
            cw = callw(rj + 0.03) * (1.0 + 1.2 * (o.vp() - 0.25))
            rho = o.rho()
            if cw > f: cw = f
            pcall = (1 - rho) * (cw / f) + rho * 0.67
            pfold = 1.0 - pcall
            if pcall > 0:
                ec = (1 - rho) * (cw / f) * eq_top(h, max(0.02, cw)) + rho * 0.67 * RND[h][1]
                ec = ec / pcall
            else:
                ec = e
            u_steal = icm(my_tot + sum(obs.bets) - obs.bets[me] + obs.pot, [x for x in [tot[k] - obs.bets[k] for k in others_alive] if x > 0])
            ev_shove = pfold * u_steal + pcall * (ec * u_win + (1 - ec) * u_lose)
            ev_call = e * u_win + (1 - e) * u_lose  # treat call as getting it in
            if ev_shove > u_fold + self.CALL_MARGIN and ev_shove >= ev_call - 0.002:
                return ('raise', obs.max_raise)
        ev_call = e * u_win + (1 - e) * u_lose
        if ev_call > u_fold + self.CALL_MARGIN + 0.002 * self.rng.random():
            if 'raise' in L and e > 0.62:
                return ('raise', obs.max_raise)
            return ('call', 0)
        return ('fold', 0) if 'fold' in L else ('check', 0)

    # -------------------------------------------------------------- postflop
    def postflop(self, obs):
        me = obs.seat
        bb = obs.blinds[1]
        L = obs.legal
        rp = self.rp
        n = len(obs.stacks)
        opps = [j for j in range(n) if j != me and obs.in_hand[j]]
        if not opps:
            return ('check', 0) if 'check' in L else ('call', 0)
        pot = obs.pot + sum(obs.bets)
        to_call = obs.to_call
        my_stack = obs.stacks[me]
        tot = self.totals(obs)
        # opponent preflop ranges -> mixture weights
        nop = len(opps)
        bettor = None
        cur = max(obs.bets)
        if cur > obs.bets[me]:
            cands = [j for j in opps if obs.bets[j] == cur]
            bettor = cands[0] if cands else None
        if bettor is not None:
            wj = self.wvec(self.opp_range_w(bettor, obs))
        else:
            if nop == 1:
                wj = self.wvec(self.opp_range_w(opps[0], obs))
            else:
                fs = [self.opp_range_w(j, obs) for j in opps]
                wj = self.wvec(sum(fs) / len(fs))
        my, groups = board_groups(obs.hole, obs.board, wj)
        gs = sorted(groups, reverse=True)
        tw = 0.0
        for _v, _w in groups: tw += _w
        street = obs.street
        outs, made = draw_outs(obs.hole, obs.board)
        unseen = 47 if street == 1 else 46
        # narrowing for postflop calls already made this hand by the relevant opponent(s)
        fc = 1.0
        if rp is not None and rp.ok:
            tgt = [bettor] if bettor is not None else opps
            acc = 0.0
            for j in tgt:
                oj = self.opp[j]
                k = rp.post_calls[j]
                if k:
                    acc += (1.0 - oj.foldbet()) ** (k * (1.0 - oj.rho_post()) * 0.8)
                else:
                    acc += 1.0
            fc = acc / len(tgt)
            if fc < 0.15: fc = 0.15
        self._fc = fc
        # postflop aggression / narrowing for the bettor
        if bettor is not None:
            o = self.opp[bettor]
            rho = o.rho_post()
            nb = rp.post_aggr[bettor] if (rp is not None and rp.ok) else 1
            facing_raise = rp is not None and rp.ok and rp.street_aggr == bettor and obs.bets[me] > 0
            fpb = o.agg() * 1.25
            if facing_raise:
                fpb = max(0.06, o.raisebet() * 1.6)
            if fpb > 1: fpb = 1.0
            if fpb < 0.12: fpb = 0.12
            fp = fpb ** (0.6 + 0.4 * max(1, nb))
            fp = (1 - rho) * fp + rho * 1.0
            # bet size: bigger bets narrower for non-random bots
            bs = to_call / float(max(1, pot - to_call))
            if bs > 1.0: fp *= (1 - 0.15 * (1 - rho))
            eall = top_eq(my, gs, tw, fc)
            etop = top_eq(my, gs, tw, fc * fp)
            bl = self.BL0 + 0.25 * rho + 0.35 * max(0.0, o.agg() - 0.4)
            if bl > 0.6: bl = 0.6
            e1 = (1 - bl) * etop + bl * eall
        else:
            eall = top_eq(my, gs, tw, fc)
            e1 = eall
        # draws: probability of improving (one card); value when hitting
        if street < 3 and not made and outs > 0:
            ph = outs / unseen
            if street == 1 and to_call >= my_stack * 0.9:
                ph = 1 - (1 - outs / 47.0) * (1 - outs / 46.0)
            e1d = e1 + (1 - e1) * ph * 0.8
        else:
            e1d = e1
        # multiway: equity vs everyone
        if nop > 1:
            others = [j for j in opps if j != bettor]
            em = e1d
            inv = (1 - min(0.99, max(0.01, em))) / max(0.01, em)
            for j in others:
                ej = max(0.01, min(0.99, eall + (1 - eall) * (ph if (street < 3 and not made and outs > 0) else 0) * 0.8))
                inv += (1 - ej) / ej
            emulti = 1.0 / (1.0 + inv)
        else:
            emulti = e1d
        if to_call > 0:
            return self.post_facing(obs, emulti, e1d, eall, pot, to_call, opps, bettor, tot, my, groups, outs, made)
        return self.post_free(obs, emulti, eall, pot, opps, tot, my, gs, tw, outs, made)

    def post_free(self, obs, e, eall, pot, opps, tot, my, gs, tw, outs, made):
        L = obs.legal
        me = obs.seat
        rp = self.rp
        bb = obs.blinds[1]
        if 'raise' not in L:
            return ('check', 0)
        my_stack = obs.stacks[me]
        street = obs.street
        nop = len(opps)
        # fold probability of opponents to a bet
        pf_all = 1.0
        for j in opps:
            o = self.opp[j]
            fb = o.foldbet()
            pf_all *= fb
        aggr_pf = rp is not None and rp.ok and rp.pf_aggr == me
        last_aggr = rp is not None and rp.ok and rp.last_aggr == me
        # candidate sizes
        best = ('check', 0)
        ev_check = e * pot * (0.9 if nop == 1 else 0.8)
        best_ev = ev_check
        spr = my_stack / float(max(1, pot))
        if spr <= 1.3:
            sizes = (spr,)
        elif self.street_strong(e):
            sizes = (0.5, 0.75, 1.1)
        else:
            sizes = (0.4, 0.66)
        fbm = 0.0
        rh = 0.0
        for j in opps:
            fbm += self.opp[j].foldbet()
            rh += self.opp[j].rho()
        fbm /= nop
        rh /= nop
        fcn = self._fc
        ph = outs / (47.0 if street == 1 else 46.0) if (not made and outs > 0 and street < 3) else 0.0
        for frac in sizes:
            B = min(my_stack, int(pot * frac))
            if B < bb: B = min(my_stack, bb)
            fr = B / float(max(1, pot))
            # rational opponents continue less vs bigger bets; random ones do not care
            cont1 = (1.0 - fbm) * (rh + (1 - rh) * min(1.6, 1.75 / (1.0 + fr)))
            if cont1 > 0.97: cont1 = 0.97
            if cont1 < 0.05: cont1 = 0.05
            ec = top_eq(my, gs, tw, fcn * max(0.08, cont1 * (1 - rh) + rh))
            if nop > 1:
                ec = 1.0 / (1.0 + nop * (1 - max(0.01, ec)) / max(0.01, ec))
                pfold = (1 - cont1) ** nop
            else:
                pfold = 1 - cont1
            if ph > 0:
                ec = ec + (1 - ec) * ph * 0.8
            ev = pfold * pot + (1 - pfold) * (ec * (pot + 2 * B) - B)
            if ev > best_ev:
                best_ev = ev
                best = ('raise', B)
        # unpredictability: c-bet / probe mix with some air when we are the aggressor
        if best[0] == 'check' and aggr_pf and street == 1 and nop <= 2 and fbm > 0.33 and rh < 0.5 and self.rng.random() < 0.35:
            best = ('raise', max(bb, int(pot * (0.4 + 0.26 * (self.rng.random() < 0.5)))))
        if best[0] == 'raise' and e > 0.9 and self.rng.random() < 0.15 and street < 3 and nop == 1:
            return ('check', 0)  # occasional slowplay of monsters
        if best[0] == 'raise':
            amt = obs.bets[me] + best[1]
            return ('raise', int(max(obs.min_raise, amt)))
        return best

    def street_strong(self, e):
        return e > 0.7

    def post_facing(self, obs, e, e1d, eall, pot, to_call, opps, bettor, tot, my, groups, outs, made):
        L = obs.legal
        me = obs.seat
        bb = obs.blinds[1]
        my_stack = obs.stacks[me]
        street = obs.street
        # pot odds
        po = to_call / float(pot + to_call)
        # ICM-based requirement when the call is a large part of our stack
        commit = to_call >= 0.33 * my_stack or (my_stack - to_call) < pot * 0.5
        need = po
        if commit:
            n = len(obs.stacks)
            bt = bettor if bettor is not None else opps[0]
            R = min(my_stack, obs.stacks[bt] + to_call)
            oth = [obs.stacks[j] for j in range(n) if j != me and j != bt and obs.stacks[j] + obs.bets[j] > 0 and (obs.stacks[j] > 0 or obs.in_hand[j])]
            oth = [x for x in oth if x > 0]
            u_fold = icm(my_stack, oth + [obs.stacks[bt] + pot])
            u_win = icm(my_stack + pot + R - to_call, oth + ([obs.stacks[bt] - (R - to_call)] if obs.stacks[bt] - (R - to_call) > 0 else []))
            u_lose = icm(my_stack - R, oth + [obs.stacks[bt] - (R - to_call) + pot + R + (R - to_call)])
            if u_win > u_lose:
                need = max(po, (u_fold - u_lose) / (u_win - u_lose))
        # implied odds for draws when deep
        eq_call = e
        if not made and outs > 0 and street < 3 and not commit:
            eq_call = e + min(0.06, (my_stack / float(max(1, pot))) * 0.01)
        # value raise
        if 'raise' in L:
            o = self.opp[bettor] if bettor is not None else None
            if e > (0.72, 0.72, 0.76, 0.80)[street] and e > need + 0.12:
                R = obs.bets[me] + to_call + int((pot + to_call) * (0.7 + 0.2 * self.rng.random()))
                if R >= 0.45 * (my_stack + obs.bets[me]):
                    R = obs.max_raise
                if e > 0.80 or (o is not None and o.rho() > 0.5) or self.rng.random() < 0.7:
                    return ('raise', int(R))
            # semi-bluff raise with big draws on flop vs foldy bettor
            if street == 1 and not made and outs >= 8 and o is not None and o.foldbet() > 0.45 and self.rng.random() < 0.3 and to_call < 0.25 * my_stack:
                R = obs.bets[me] + to_call + int((pot + to_call) * 0.8)
                return ('raise', int(R))
        if eq_call >= need + 0.01:
            return ('call', 0)
        return ('fold', 0)


